  values ('deal:crystal-palace-football-club:woody-johnson:2025-06-23', '2025-06-23', 'Agreed 23 June 2025; completed 24 July 2025', 'stake_sale', 'sports', 'football', 'Crystal Palace Football Club', 'club', 'England', (select id from public.sports_teams where external_key = 'premier-league--crystal-palace'), null, 'Woody Johnson', 'individual', (select id from public.companies where lower(name) = lower('Woody Johnson') limit 1), (select id from public.sports_investors where lower(name) = lower('Woody Johnson') limit 1), 'Eagle Football Holdings (John Textor)', 43, 190000000, 'GBP', 550000000, 'GBP', 'Woody Johnson buys Textor''s 43% stake in Crystal Palace for about £190m', 'New York Jets owner Woody Johnson agreed to buy Eagle Football''s 43% shareholding for about £190m (about $254m), at a reported club valuation of £550m. The sale removed a UEFA multi-club ownership obstacle to Palace playing in the Europa League; completion was confirmed on 24 July 2025 subject to Premier League and WSL approval.', 'Sportico', 'https://www.sportico.com/business/team-sales/2025/crystal-palace-sale-woody-johnson-1234857577/', 'web_research')
